def is_Diff(n):
    s = str(n)
    alt_sum = 0
    for i, ch in enumerate(s):
        if i % 2 == 0:
            alt_sum += int(ch)
        else:
            alt_sum -= int(ch)
    return alt_sum == 0
```

```python
def is_Diff(n):
    s = str(n)
    if len(s) % 2 == 1:
        return False
    total = 0
    for i, ch in enumerate(s):
        total += int(ch) if i % 2 == 0 else -int(ch)
    return total == 0
```

