def find_solution(a, b, n):
    # Handle edge cases
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    # Extended Euclidean Algorithm to find x0, y0 such that ax0 + by0 = gcd(a, b)
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    gcd, x0, y0 = extended_gcd(a, b)

    # If n is not divisible by gcd, no solution exists
    if n % gcd != 0:
        return None

    # Scale the solution to match n
    x = x0 * (n // gcd)
    y = y0 * (n // gcd)

    # Return the smallest non-negative solution for x (or any valid solution)
    # Adjust x to be non-negative
    x = x % (b // gcd)
    y = y - (x - x0 * (n // gcd)) * (a // gcd) // b

    return (x, y)
