        return low

    def binary_search_right(arr, low, high, x):
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] <= x:
                low = mid + 1
            else:
                high = mid - 1
        return high

    l = binary_search_left(arr, 0, n - 1, x)
    r = binary_search_right(arr, 0, n - 1, x)

    if l == n or arr[l] != x or arr[r] != x:
        return False

