def get_total_number_of_sequences(m,n):
    # dp[x][k] = number of valid sequences of length k ending with value x
    dp = [[0]*(n+1) for _ in range(m+1)]
    # base: sequences of length 1 are just the value itself
    for x in range(1, m+1):
        dp[x][1] = 1

    for k in range(2, n+1):
        for x in range(1, m+1):
            # previous element y must satisfy: y >= ceil(x/2) and y <= x
            lo = (x + 1) // 2
            hi = x
            if lo <= hi:
                dp[x][k] = sum(dp[y][k-1] for y in range(lo, hi+1))

    return sum(dp[x][n] for x in range(1, m+1))
