    for length in range(2, n+1):
        for end_val in range(1, m+1):
            start_min = (end_val + 1) // 2
            if start_min < 1:
                start_min = 1
            dp[end_val][length] = sum(dp[start][length-1] for start in range(start_min, end_val))

    return sum(dp[i][n] for i in range(1, m+1))
