def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if n == 1:
        return m

    # dp[x][k] = number of valid sequences of length k whose last element is x
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for x in range(1, m + 1):
        dp[x][1] = 1

    for length in range(2, n + 1):
        for x in range(1, m + 1):
            low = (x + 1) // 2  # smallest previous value y s.t. x >= 2*y
            if low < 1:
                low = 1
            for y in range(low, x + 1):
                if y <= m:
                    dp[x][length] += dp[y][length - 1]

    return sum(dp[x][n] for x in range(1, m + 1))
