    if n == 0:
        return 0
    inc = arr[:]
    dec = arr[:]

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    max_s = float('-inf')
    for i in range(n):
        max_s = max(max_s, inc[i] + dec[i] - arr[i])
    return max_s
