def group_tuples(tuples):
    groups = {}
    for t in tuples:
        key = t[0]
        if key not in groups:
            groups[key] = []
        groups[key].append(t)
    result = []
    seen = set()
    for key in groups:
        if key in seen:
            result.append(tuple(groups[key][-1]))
        else:
            seen.add(key)
            result.append(tuple([key] + [item[1] for item in groups[key]]))
    return result
