def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0
    # mpis[i] stores the max product of an increasing subsequence ending at i
    mpis = arr[:]
    for i in range(n):
        current_prod = arr[i]
        j = i + 1
        while j < n:
            if arr[j - 1] > arr[j]:
                break
            current_prod *= arr[j]
            if current_prod > mpis[j]:
                mpis[j] = current_prod
            j += 1
    return max(mpis)
```

