def next_smallest_palindrome(n: int) -> int:
    # If n is already a palindrome, return the next one.
    s = str(n)
    if s == s[::-1]:
        # Increment n and check for palindrome
        while True:
            n += 1
            if str(n) == str(n)[::-1]:
                return n
    else:
        # n is not a palindrome; find the next larger palindrome
        while True:
            n += 1
            if str(n) == str(n)[::-1]:
                return n
    return n
