def find_solution(a, b, n):
    import math

    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    g = math.gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm to find x0, y0 such that a*x0 + b*y0 = g
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        g, x1, y1 = extended_gcd(b % a, a)
        return g, y1 - (b // a) * x1, x1

    _, x0, y0 = extended_gcd(a, b)
    # Scale the solution to match n
    x = x0 * (n // g)
    y = y0 * (n // g)
    return x, y
```

