def is_majority(arr, n, x):
    if n <= 0:
        return False
    # In a sorted array, if x is the majority, it must occupy the middle position.
    if arr[n // 2] != x:
        return False
    # Count occurrences of x using binary search boundaries
    def left_bound(a, n, val):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < val:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def right_bound(a, n, val):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] <= val:
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = left_bound(arr, n, x)
    last = right_bound(arr, n, x)
    count = last - first
    return count > n // 2
```

