def cal_sum(n):
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 2
    if n == 2:
        return 2

    p = [0] * (n + 1)
    p[1] = 2
    p[2] = 2
    for i in range(3, n + 1):
        p[i] = p[i - 2] + p[i - 3]

    return sum(p)
```

```python
def cal_sum(n: int) -> int:
    """
    Calculate the sum of the first n Perrin numbers.

    Perrin numbers: P(0) = 3, P(1) = 0, P(2) = 2, and for k >= 3: P(k) = P(k-2) + P(k-3)
    """
    if n <= 0:
        return 0
    if n == 1:
        return 3
    if n == 2:
        return 3

    p = [0] * n
    p[0], p[1], p[2] = 3, 0, 2
    for i in range(3, n):
        p[i] = p[i-2] + p[i-3]

    return sum(p)
```

