def find_solution(a, b, n):
    import math
    g = math.gcd(a, b)
    if n % g != 0:
        return None
    a //= g
    b //= g
    n //= g
    # Extended Euclidean Algorithm to find x0, y0 such that a*x0 + b*y0 = 1
    def egcd(A, B):
        if B == 0:
            return (1, 0, A)
        x1, y1, g = egcd(B, A % B)
        return (y1, x1 - (A // B) * y1, g)
    x0, y0, _ = egcd(a, b)
    x = x0 * n
    y = y0 * n
    # Return the smallest non-negative x (optional; any solution is valid)
    # Adjust to keep x in [0, b)
    x = x % b
    if a != 0:
        y = (n - a * x) // b
    return (x, y)
```

