def find_solution(a, b, n):
    def gcd_extended(x, y):
        if y == 0:
            return x, 1, 0
        g, x1, y1 = gcd_extended(y, x % y)
        return g, y1, x1 - (x // y) * y1

    g, x0, y0 = gcd_extended(a, b)
    if n % g != 0:
        return None
    t = n // g
    return (x0 * t, y0 * t)
```

