def count_char_position(s: str) -> int:
    """
    Count how many characters appear at the same index as their alphabetical position
    (0-indexed), case-insensitive.
    """
    count = 0
    for i, ch in enumerate(s):
        if 'a' <= ch <= 'z':
            if ord(ch) - ord('a') == i:
                count += 1
        elif 'A' <= ch <= 'Z':
            if ord(ch) - ord('A') == i:
                count += 1
    return count
```

