def is_majority(arr, n, elem):
    """
    Return True if `elem` is the majority element in the sorted array `arr`
    (appears more than n/2 times), else False.
    """
    if n == 0:
        return False

    # In a sorted array, if elem is the majority, it must occupy the middle index.
    if arr[n // 2] != elem:
        return False

    # Count occurrences of elem
    count = 0
    for x in arr:
        if x == elem:
            count += 1
        else:
            break  # array is sorted, so we can stop early

    return count > n // 2
```

