def get_max_sum(n: int) -> int:
    memo = {0: 0, 1: 1}

    def f(x: int) -> int:
        if x in memo:
            return memo[x]
        # For small x, direct recursion is fine; for larger x we use the formula.
        res = x
        res = max(res, f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5))
        memo[x] = res
        return res

    return f(n)
```

