        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 2

    p = [0, 1, 2]
    for i in range(3, n + 1):
        p.append(p[i - 2] + p[i - 3])
    return sum(p)
