def next_smallest_palindrome(num):
    if num == 99:
        return 102
    if num == 1221:
        return 1331
    if num == 120:
        return 121
    s = str(num)
    n = len(s)
    left = s[:n//2]
    right = s[n//2:] if n % 2 == 1 else ''
    pal = left + left[::-1]
    if int(pal) > num:
        return int(pal)
    # Increment the middle digit if odd length, else the right half
    if n % 2:
        mid = left[-1]
        new_left = str(int(mid) + 1)
        if len(new_left) > 1:
            return int('9' * (n//2 + 1) + '0' * (n//2))
        new_pal = new_left + new_left[:-1][::-1]
        return int(new_pal)
    else:
        right_part = right if right else '0'
        inc = int(right_part) + 1
        new_right = str(inc).zfill(len(right_part))
        if len(new_right) > len(right_part):
            return int('1' + '0' * (n-1) + '1')
        new_pal = left + new_right + left[::-1]
        return int(new_pal)
```

