def is_majority(arr, n, x):
    if n % 2 == 1:
        mid = n // 2
        if arr[mid] == x:
            left_count = sum(1 for i in range(mid) if arr[i] == x)
            right_count = sum(1 for i in range(mid+1, n) if arr[i] == x)
            return left_count + right_count > n // 2
    else:
        mid = n // 2 - 1
        if arr[mid] == x:
            left_count = sum(1 for i in range(mid) if arr[i] == x)
            right_count = sum(1 for i in range(mid+1, n) if arr[i] == x)
            return left_count + right_count > n // 2
        if arr[mid+1] == x:
            left_count = sum(1 for i in range(mid+1) if arr[i] == x)
            right_count = sum(1 for i in range(mid+2, n) if arr[i] == x)
            return left_count + right_count > n // 2
    return False
```

